"""Which line of a three-line filter registration is the one that crashes?

`class CustomFilter {} stream_filter_register(...)` SIGSEGVs, and a segfault says nothing about
where. Narrowing by SOURCE, one construct at a time, names the culprit before any assembler is
read — the cheaper half of the two techniques, and the one that decides where to point lldb.
"""
import pathlib, subprocess, os, shutil

D = pathlib.Path('/private/tmp/claude-501/-Users-guillaumeloulier-PhpstormProjects-oss-elephc--claude-worktrees-streams-csv-signature/c8dbe38f-1f79-484f-9b83-62bacab9ca56/scratchpad/uv/segvnarrow')
ELEPHC = '/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/target/debug/elephc'

CASES = {
    'register only, plain class': '''<?php
class CustomFilter {}
var_dump(stream_filter_register("custom.filter", "CustomFilter"));
''',
    'register, no echo of result': '''<?php
class CustomFilter {}
stream_filter_register("custom.filter", "CustomFilter");
echo "alive\\n";
''',
    'register with a literal class name, no class declared': '''<?php
var_dump(stream_filter_register("custom.filter", "Nope"));
''',
    'no register at all, just the class': '''<?php
class CustomFilter {}
echo "alive\\n";
''',
    'register, then nothing else': '''<?php
class CustomFilter {}
stream_filter_register("custom.filter", "CustomFilter");
''',
    'two registers': '''<?php
class CustomFilter {}
stream_filter_register("a", "CustomFilter");
stream_filter_register("b", "CustomFilter");
echo "alive\\n";
''',
    'register a php_user_filter subclass': '''<?php
class Up extends php_user_filter {}
var_dump(stream_filter_register("up", "Up"));
''',
    'register then get_filters': '''<?php
class CustomFilter {}
stream_filter_register("custom.filter", "CustomFilter");
var_dump(in_array("custom.filter", stream_get_filters()));
''',
}

if D.exists():
    shutil.rmtree(D)
D.mkdir(parents=True)

for name, src in CASES.items():
    sub = D / str(abs(hash(name)) % 100000)
    sub.mkdir()
    f = sub / 'p.php'
    f.write_text(src)
    php = subprocess.run(['php', '-n', str(f)], capture_output=True, text=True, cwd=str(sub), timeout=30)
    build = subprocess.run([ELEPHC, 'build', str(f), '-o', str(sub / 'out')],
                           capture_output=True, text=True, cwd=str(sub), timeout=300)
    if build.returncode != 0:
        print(f'{name:48s} BUILD FAILED: {(build.stdout + build.stderr).strip()[:200]}')
        continue
    run = subprocess.run([str(sub / 'out')], capture_output=True, text=True, cwd=str(sub), timeout=60)
    verdict = 'same' if run.stdout == php.stdout and run.returncode == php.returncode else 'DIFFERS'
    sig = f' signal {-run.returncode}' if run.returncode < 0 else ''
    print(f'{name:48s} {verdict}{sig}')
    if verdict == 'DIFFERS':
        print(f'    php:    {php.stdout!r} rc={php.returncode}')
        print(f'    elephc: {run.stdout!r} rc={run.returncode} stderr={run.stderr.strip()[:120]!r}')
